          {section === 'settings' && <div className=\"settings-panel\"><Text variant=\"header-1\">Рабочее пространство</Text><label className=\"field\">Название магазина<TextInput value={shopName} onUpdate={setShopName} size=\"l\"/></label><div className=\"setting-row\"><div><strong>Уведомления по email</strong><p className=\"secondary\">Получать информацию о новых заказах</p></div><Switch checked={emailNotifications} onUpdate={setEmailNotifications}/></div><div className=\"setting-row\"><div><strong>Компактное меню</strong><p className=\"secondary\">Показывать только иконки разделов</p></div><Switch checked={compact} onUpdate={setCompact}/></div><div className=\"settings-footer\"><Button view=\"action\" size=\"l\" disabled={"'!shopName.trim()} onClick={() => {saveStorage('"'potok-shop', shopName.trim());saveStorage('potok-email-notifications', emailNotifications);setToast('Настройки сохранены в этом браузере');}}>Сохранить изменения</Button><span className=\"secondary\">Демонстрационное рабочее пространство</span></div></div>}
          <footer className=\"page-footer\"><span>© 2026 Поток</span>{section === 'orders' ? <span><Icon data={Grip} size={14}/>Перетаскивайте заголовки, чтобы менять порядок колонок</span> : <span>Ваш бизнес. В одном потоке.</span>}<span className=\"system-status\"><i className=\"live-dot\"/>Все системы работают</span></footer>
        </main></div>}/>
    <Dialog open={dialog === 'create'} title=\"Новый заказ\" onClose={() => setDialog(null)}><p className=\"dialog-description\">Добавьте заказ — он сразу появится в таблице.</p><form onSubmit={createOrder} className=\"order-form\"><label className=\"field\">Имя клиента<TextInput size=\"l\" placeholder=\"Анна Смирнова\" value={newName} onUpdate={setNewName} autoFocus/></label><label className=\"field\">Email<TextInput size=\"l\" type=\"email\" placeholder=\"anna@example.com\" value={newEmail} onUpdate={setNewEmail}/></label><div className=\"form-row\"><label className=\"field\">Сумма, ₽<TextInput size=\"l\" type=\"number\" value={newAmount} onUpdate={setNewAmount} placeholder=\"0\" controlProps={{min: 0.01, step: 0.01}}/></label><label className=\"field\">Статус<Select size=\"l\" options={statusOptions} value={[newStatus]} onUpdate={value => setNewStatus(value[0] as Status)}/></label></div>{formError && <p className=\"form-error\" role=\"alert\">{formError}</p>}<div className=\"dialog-actions\"><Button size=\"l\" view=\"outlined\" onClick={() => setDialog(null)}>Отмена</Button><Button size=\"l\" view=\"action\" type=\"submit\"><Icon data={Plus}/>Создать заказ</Button></div></form></Dialog>
    <Dialog open={dialog === 'filters'} title=\"Фильтры заказов\" onClose={() => setDialog(null)}><div className=\"order-form\"><label className=\"field\">Оплата<Select size=\"l\" value={[draftPayment]} onUpdate={v => setDraftPayment(v[0])} options={[{value: 'all', content: 'Любая оплата'}, {value: 'paid', content: 'Оплачен'}, {value: 'waiting', content: 'Ожидает оплаты'}, {value: 'refund', content: 'Возврат'}]}/></label><label className=\"field\">Минимальная сумма, ₽<TextInput size=\"l\" type=\"number\" value={draftMin} onUpdate={setDraftMin} placeholder=\"Без ограничений\" controlProps={{min: 0}}/></label><div className=\"dialog-actions\"><Button size=\"l\" view=\"flat\" onClick={() => {setDraftPayment('all');setDraftMin('');}}>Сбросить</Button><Button size=\"l\" view=\"action\" onClick={() => {setPaymentFilter(draftPayment);setMinAmount(draftMin);setDialog(null);}}>Применить</Button></div></div></Dialog>
    <Dialog open={dialog === 'columns'} title=\"Настройка колонок\" onClose={() => setDialog(null)}><p className=\"dialog-description\">Выберите видимые колонки. Меняйте порядок стрелками или перетаскивайте заголовки таблицы.</p><div className=\"column-options\">{table.getAllLeafColumns().filter(c => c.getCanHide()).map(column => <div className=\"column-option\" key={column.id}><Checkbox checked={column.getIsVisible()} onUpdate={v => column.toggleVisibility(v)}>{typeof column.columnDef.header === 'string' ? column.columnDef.header : column.id}</Checkbox><div>{[-1,1].map(direction => <Button key={direction} view=\"flat\" disabled={columnOrder.indexOf(column.id) + direction < 1 || columnOrder.indexOf(column.id) + direction >= columnOrder.length - 1} aria-label={direction === -1 ? 'Переместить влево' : 'Переместить вправо'} onClick={() => {const next = [...columnOrder]; const i = next.indexOf(column.id); [next[i],next[i + direction]] = [next[i + direction],next[i]];setColumnOrder(next);}}><Icon data={direction === -1 ? ChevronLeft : ChevronRight}/></Button>)}</div></div>)}</div><div className=\"dialog-actions\"><Button view=\"flat\" onClick={() => {setColumnVisibility({});setColumnOrder(defaultColumnOrder);}}>По умолчанию</Button><Button view=\"action\" onClick={() => setDialog(null)}>Готово</Button></div></Dialog>
    <Dialog open={dialog === 'help'} title=\"Добро пожаловать в Поток\" onClose={() => setDialog(null)}><p className=\"dialog-description\">Управление магазином без лишних движений.</p><div className=\"help-topics\">{[{icon: Check, title: 'Выделение заказов', text: 'Отмечайте заказы или целые группы, чтобы менять их статус и экспортировать вместе.'}, {icon: Layers, title: 'Группировка по статусу', text: 'Кнопка «По статусу» объединяет заказы в группы. Стрелка рядом с группой сворачивает её.'}, {icon: Grip, title: 'Таблица под ваши задачи', text: 'Перетаскивайте заголовки колонок. В меню «Колонки» можно скрыть поля или изменить порядок стрелками.'}].map(item => <div className=\"help-topic\" key={item.title}><Icon data={item.icon} size={22}/><div><strong>{item.title}</strong><p>{item.text}</p></div></div>)}</div><p className=\"demo-note\">Это демоверсия: заказы и настройки сохраняются локально в вашем браузере.</p><Button view=\"action\" size=\"l\" width=\"max\" onClick={() => setDialog(null)}>Всё понятно</Button></Dialog>
    <Dialog open={dialog === 'notifications'} title=\"Уведомления\" onClose={() => setDialog(null)}><div className=\"notification-item\"><span className=\"notification-icon\"><Icon data={ShoppingBag} size={21}/></span><div><strong>Новые заказы ждут вас</strong><p className=\"secondary\">Заказов со статусом «Новый»: {counts.new}. Откройте список, чтобы начать обработку.</p><Button view=\"flat\" onClick={() => {setSection('orders');resetFilters();setActiveStatus('new');setDialog(null);setNotificationRead(true);}}>Перейти к заказам <Icon data={ArrowRight}/></Button></div></div><Button view=\"outlined\" width=\"max\" onClick={() => {setNotificationRead(true);setDialog(null);setToast('Все уведомления прочитаны');}}>Отметить прочитанными</Button></Dialog>
    <Dialog open={"'!!detail} title={detail ? `Заказ #${detail.id}` : '"'Заказ'} onClose={() => setDetailId(null)}>{detail && <><Customer order={detail}/><div className=\"order-details\"><div><span>Дата создания</span><strong>{formatDate(detail.date)}, {detail.time}</strong></div><div><span>Количество товаров</span><strong>{detail.items}</strong></div><div><span>Сумма заказа</span><strong>{money(detail.amount)}</strong></div><div><span>Оплата</span><strong>{detail.payment === 'paid' ? 'Оплачен' : detail.payment === 'waiting' ? 'Ожидает оплаты' : 'Возврат'}</strong></div></div><label className=\"field\">Статус заказа<Select size=\"l\" value={[detail.status]} options={statusOptions} onUpdate={v => updateStatus(detail.id, v[0] as Status)}/></label><div className=\"dialog-actions\"><Button view=\"outlined\" onClick={() => exportOrders([detail])}><Icon data={ArrowDownToLine}/>Экспорт</Button><Button view=\"action\" onClick={() => setDetailId(null)}>Готово</Button></div></>}</Dialog>
    {toast && <div className=\"toast\" role=\"status\"><span><Icon data={CircleCheck} size={19}/>{toast}</span><Button view=\"flat\" aria-label=\"Закрыть уведомление\" onClick={() => setToast('')}><Icon data={Xmark} size={15}/></Button></div>}
  </>;
}
EOF"

