.selection-toolbar {padding: var(--g-spacing-3) var(--g-spacing-5); display: flex; align-items: center; gap: var(--g-spacing-3); background: var(--g-color-base-selection); border-top: 1px solid var(--g-color-base-selection-hover); color: var(--g-color-text-brand);}
.selection-toolbar>span {margin-right: auto;}
.selection-toolbar strong {font-size: 12px;}
.empty-state {padding: var(--g-spacing-10); min-height: 300px; display: flex; flex-direction: column; align-items: center; justify-content: center;}
.empty-icon {display: grid; place-items: center; width: 56px; height: 56px; border-radius: 50%; background: var(--g-color-base-generic); color: var(--g-color-text-secondary); margin-bottom: var(--g-spacing-4);}
.empty-state p {color: var(--g-color-text-secondary); margin-bottom: var(--g-spacing-5);}
.dialog {padding: var(--g-spacing-7); width: 480px; max-width: calc(100vw - 32px);}
.dialog-title {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-5);}
.dialog-description {color: var(--g-color-text-secondary); line-height: 1.6; margin: 0 0 var(--g-spacing-5); font-size: 13px;}
.order-form {display: flex; flex-direction: column; gap: var(--g-spacing-5);}
.field {display: flex; flex-direction: column; gap: var(--g-spacing-2); font-size: 12px; flex: 1; min-width: 0;}
.form-row {display: flex; gap: var(--g-spacing-4);}
.dialog-actions {display: flex; justify-content: flex-end; align-items: center; gap: var(--g-spacing-3); padding-top: var(--g-spacing-4); margin-top: var(--g-spacing-2);}
.form-error {color: var(--g-color-text-danger); font-size: 12px;}
.column-options {display: flex; flex-direction: column;}
.column-option {display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-2) 0;}
.help-topics {display: flex; flex-direction: column; gap: var(--g-spacing-5);}
.help-topic {display: flex; align-items: flex-start; gap: var(--g-spacing-4);}
.help-topic>.g-icon {color: var(--g-color-text-brand); flex-shrink: 0;}
.help-topic p {margin-top: var(--g-spacing-2); line-height: 1.6; color: var(--g-color-text-secondary);}
.demo-note {padding: var(--g-spacing-3); border-radius: var(--g-border-radius-m); background: var(--g-color-base-generic); color: var(--g-color-text-secondary); font-size: 12px; line-height: 1.6; margin-block: var(--g-spacing-5);}
.notification-item {display: flex; align-items: flex-start; gap: var(--g-spacing-4); padding-bottom: var(--g-spacing-6);}
.notification-icon {color: var(--g-color-text-brand); padding: var(--g-spacing-3); border-radius: var(--g-border-radius-m); background: var(--g-color-base-selection);}
.notification-item p {line-height: 1.6;}
.order-details {display: flex; flex-direction: column; gap: var(--g-spacing-4); padding: var(--g-spacing-6) 0; margin: var(--g-spacing-4) 0; border-block: 1px solid var(--g-color-line-generic);}
.order-details>div {display: flex; justify-content: space-between; font-size: 12px; gap: var(--g-spacing-3);}
.order-details>div>span {color: var(--g-color-text-secondary);}
.order-details strong {font-weight: 500;}
.toast {position: fixed; z-index: 10000; bottom: 26px; left: 50%; transform: translateX(-50%); border: 1px solid var(--g-color-base-selection-hover); border-radius: var(--g-border-radius-l); background: var(--g-color-base-background); box-shadow: 0 6px 24px var(--g-color-sfx-shadow); padding: var(--g-spacing-3) var(--g-spacing-4); display: flex; gap: var(--g-spacing-5); align-items: center; max-width: calc(100vw - 32px);}
.toast>span {display: flex; align-items: center; gap: var(--g-spacing-3); font-size: 12px;}
.toast>span>.g-icon {color: var(--g-color-text-brand); flex-shrink: 0;}
.home-panel, .settings-panel, .users-panel {background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); padding: var(--g-spacing-6);}
.section-heading {display: flex; align-items: center; justify-content: space-between; margin-bottom: var(--g-spacing-5);}
.recent-order {display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: var(--g-spacing-4); align-items: center; padding: var(--g-spacing-4) 0; border-top: 1px solid var(--g-color-line-generic);}
.recent-order>.status-badge {justify-self: start;}
.recent-order>strong {text-align: right; font-weight: 500;}
.users-search {max-width: 360px; margin-bottom: var(--g-spacing-6);}
.users-grid {display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: var(--g-spacing-4);}
.user-card {padding: var(--g-spacing-5); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l);}
.user-card-stats {display: flex; justify-content: space-between; margin: var(--g-spacing-5) 0; gap: var(--g-spacing-3); color: var(--g-color-text-secondary); font-size: 11px;}
.user-card-stats span {display: flex; flex-direction: column; gap: var(--g-spacing-2);}
.user-card-stats strong {color: var(--g-color-text-primary); font-size: 14px;}
.settings-panel {max-width: 720px; display: flex; flex-direction: column; gap: var(--g-spacing-6);}
.settings-panel>.field {max-width: 400px;}
.setting-row {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); padding-top: var(--g-spacing-5); border-top: 1px solid var(--g-color-line-generic);}
.setting-row strong {font-weight: 500;}
.setting-row p {font-size: 12px; margin-bottom: 0;}
.settings-footer {display: flex; align-items: center; gap: var(--g-spacing-4); padding-top: var(--g-spacing-4);}
.settings-footer>span {font-size: 10px;}
@media (min-width: 1600px) {.main {padding: var(--g-spacing-9) var(--g-spacing-10);} .orders-table .order-cell {height: 70px;} .customer-copy>span {font-size: 12px;} .customer-copy .customer-email {font-size: 11px;}}
@media (max-width: 1200px) {.main {padding: var(--g-spacing-6);} .topbar {padding-inline: var(--g-spacing-6);} .metric-card {padding: var(--g-spacing-4);} .metric-value {font-size: 25px;} .metric-bottom {gap: var(--g-spacing-1); font-size: 9px;} .status-tabs {gap: var(--g-spacing-3);} .status-tab {font-size: 11px;} .tab-count {margin-left: var(--g-spacing-1);} .page-footer>span:nth-child(2) {display: none;} .users-grid {grid-template-columns: repeat(2,minmax(0,1fr));}}
@media (max-width: 1000px) {.metrics {gap: var(--g-spacing-3);} .metric-bottom>.secondary {display: none;} .page-heading {align-items: flex-start;} .heading-actions {padding-top: var(--g-spacing-2);} .order-search {min-width: 160px;} .columns-button-label {display: none;} .table-toolbar {padding-inline: var(--g-spacing-3);} .table-footer {flex-wrap: wrap;} .page-size-label {display: none;} .group-button .toggle-indicator {display: none;} .topbar-actions .global-search {display: none;} .recent-order {grid-template-columns: 2fr 1fr 1fr;} .recent-order>.g-button {display: none;}}
@media (max-width: 700px) {.main {padding: var(--g-spacing-5) var(--g-spacing-4);} .topbar {height: 60px; padding-inline: var(--g-spacing-4);} .breadcrumbs {font-size: 11px; gap: var(--g-spacing-2);} .breadcrumbs>span:first-child {display: none;} .breadcrumbs>.g-icon {display: none;} .topbar-actions {gap: 0;} .topbar-divider {display: none;} .page-heading {flex-direction: column; margin-bottom: var(--g-spacing-5);} .page-title {font-size: 26px;} .page-description {font-size: 11px;} .metrics {grid-template-columns: repeat(2,minmax(0,1fr));} .metric-value {font-size: 24px;} .metric-card {padding: var(--g-spacing-3);} .metric-top {font-size: 10px;} .metric-icon {height: 22px; width: 22px;} .metric-bottom {margin-top: var(--g-spacing-2);} .overview-caption {font-size: 9px;} .overview-caption .g-button {font-size: 9px;} .table-toolbar {flex-wrap: wrap; padding: var(--g-spacing-3);} .order-search {width: 100%; max-width: none; flex-basis: 100%;} .toolbar-spacer {display: none;} .table-toolbar>.g-button:last-child {margin-left: auto;} .group-button {flex: 1;} .status-tabs {padding-inline: var(--g-spacing-3); gap: var(--g-spacing-3);} .status-tab {height: 46px;} .table-footer {padding: var(--g-spacing-3); gap: var(--g-spacing-3);} .pagination {gap: var(--g-spacing-1); width: 100%; justify-content: space-between;} .page-buttons {gap: 0;} .page-buttons .g-button {min-width: 24px;} .page-piece {gap: 0;} .pagination-dots {padding: 0;} .selection-toolbar {flex-wrap: wrap; gap: var(--g-spacing-2);} .selection-toolbar>span {width: 100%;} .system-status {font-size: 8px;} .users-grid {grid-template-columns: 1fr;} .users-panel, .settings-panel, .home-panel {padding: var(--g-spacing-4);} .settings-footer {flex-direction: column; align-items: flex-start;} .recent-order {grid-template-columns: 1fr 1fr;} .recent-order>.status-badge {display: none;} .home-panel .section-heading {align-items: flex-start; gap: var(--g-spacing-2);} .home-panel .section-heading>.g-button {font-size: 11px;} .dialog {padding: var(--g-spacing-5);} .form-row {flex-direction: column;} .order-details>div {font-size: 11px;}}
@media (prefers-reduced-motion: reduce) {* {scroll-behavior: auto "'!important; transition: none !important;}}
EOF
npm run build'

item.command:
/bin/bash -lc "cat > src/styles.css <<'EOF'
.g-root_theme_light {
  --g-color-base-brand: #2d7562;
  --g-color-base-brand-hover: #246451;
  --g-color-base-selection: #e9f2ee;
  --g-color-base-selection-hover: #deebe5;
  --g-color-line-brand: #2d7562;
  --g-color-text-brand: #2d7562;
  --g-color-text-brand-heavy: #225c4b;
  --g-color-text-brand-contrast: #ffffff;
  --g-color-text-link: #2d7562;
  --g-color-text-link-hover: #205b49;
  --g-color-line-focus: #2d7562;
  --g-color-base-background: #ffffff;
  --g-color-base-float: #ffffff;
  --g-color-base-generic: #f4f5f5;
  --g-color-base-generic-hover: #ecefed;
  --g-color-line-generic: #e9ecea;
  --g-color-line-generic-hover: #d6ddd9;
  --g-color-text-primary: #252b29;
  --g-color-text-secondary: #858b88;
  --g-color-text-hint: #a6aca8;
  --g-color-text-positive: #368266;
  --g-color-text-info: #4b7cc3;
  --g-color-text-warning: #ad803b;
  --g-color-text-danger: #c47875;
  --g-color-base-positive-light: #eef6f0;
  --g-color-base-info-light: #eef3fc;
  --g-color-base-warning-light: #fbf5e9;
  --g-color-base-danger-light: #fcf0ef;
  --app-surface: #fafbfa;
  --app-sidebar: #f9faf9;
  --app-soft-green: #edf4f0;
  --app-purple: #8676ad;
  --app-purple-light: #f2eff8;
  --g-text-body-font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --g-text-header-font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --g-text-subheader-font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --g-text-display-font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --g-text-display-1-font-size: 30px;
  --g-text-display-1-line-height: 38px;
  --g-text-body-1-font-size: 13px;
  --g-text-body-2-font-size: 14px;
  --g-border-radius-m: 7px;
  --g-border-radius-l: 10px;
  --g-border-radius-xl: 13px;
  --g-button-border-radius: var(--g-border-radius-m);
  --g-text-input-border-radius: var(--g-border-radius-m);
}
* {box-sizing: border-box;}
body {margin: 0; -webkit-font-smoothing: antialiased;}
body, button, input {font-family: var(--g-text-body-font-family);}
button, a {-webkit-tap-highlight-color: transparent;}
.app-navigation {--gn-aside-header-background-color: var(--app-sidebar); --gn-aside-header-divider-vertical-color: var(--g-color-line-generic); --gn-aside-header-padding-top: var(--g-spacing-3);}
.brand {height: 52px; display: flex; align-items: center; gap: var(--g-spacing-3); padding: 0 var(--g-spacing-6); font-size: 29px; font-weight: 750; letter-spacing: -1.5px;}
.brand-compact {padding: 0; justify-content: center;}
.brand-period {color: var(--g-color-text-brand);}
.brand-mark {width: 30px; height: 32px; position: relative; display: inline-block; flex-shrink: 0;}
.brand-mark span {position: absolute; width: 13px; height: 21px; border-radius: var(--g-border-radius-xs); background: var(--g-color-base-brand); transform: skewY(-25deg);}
.brand-mark span:nth-child(1) {left: 0; top: 6px;}
.brand-mark span:nth-child(2) {left: 10px; top: 2px; opacity: .78;}
.brand-mark span:nth-child(3) {left: 20px; top: 6px; width: 8px; opacity: .48;}
.above-menu {padding: var(--g-spacing-5) var(--g-spacing-4) var(--g-spacing-2);}
.above-menu.is-compact {padding: var(--g-spacing-3) 0;}
.workspace-picker {display: flex; align-items: center; gap: var(--g-spacing-2); background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-3) var(--g-spacing-2); border-radius: var(--g-border-radius-m); margin-bottom: var(--g-spacing-7);}
.workspace-icon {display: grid; place-items: center; width: 32px; height: 32px; background: var(--g-color-base-generic); border-radius: var(--g-border-radius-m); flex-shrink: 0;}
.workspace-picker>div {display: flex; min-width: 0; flex: 1; flex-direction: column; gap: var(--g-spacing-1);}
.workspace-picker strong {font-size: 12px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;}
.workspace-picker>div>span {font-size: 10px; color: var(--g-color-text-secondary); white-space: nowrap;}
.menu-caption {font-size: 10px; color: var(--g-color-text-secondary); letter-spacing: 1.2px; margin-left: var(--g-spacing-2); font-weight: 500;}
.nav-item {margin-bottom: var(--g-spacing-2); color: var(--g-color-text-secondary); font-size: 13px;}
.nav-item-active {color: var(--g-color-text-brand); font-weight: 600;}
.nav-count {padding: 2px var(--g-spacing-2); background: var(--g-color-base-background); border: 1px solid var(--g-color-base-selection-hover); border-radius: var(--g-border-radius-s); font-size: 10px; font-weight: 500; color: var(--g-color-text-brand);}
.sidebar-footer {padding: var(--g-spacing-2) var(--g-spacing-2) 0;}
.help-card {border: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-4); border-radius: var(--g-border-radius-l); background: var(--g-color-base-background); margin-bottom: var(--g-spacing-6);}
.help-card-icon {display: block; color: var(--g-color-text-brand); margin-bottom: var(--g-spacing-3);}
.help-card strong {font-size: 12px; font-weight: 600;}
.help-card p {color: var(--g-color-text-secondary); font-size: 11px; line-height: 1.7; margin: var(--g-spacing-2) 0 var(--g-spacing-4);}
.help-card .g-button {font-size: 11px;}
.sidebar-profile {display: flex; align-items: center; gap: var(--g-spacing-2); border-top: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-5) 0 var(--g-spacing-2);}
.sidebar-profile>div {flex: 1; min-width: 0; display: flex; flex-direction: column; gap: var(--g-spacing-1);}
.sidebar-profile strong {font-size: 11px; white-space: nowrap; font-weight: 600;}
.sidebar-profile>div>span {font-size: 10px; color: var(--g-color-text-secondary);}
.profile-avatar, .top-avatar {width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; background: var(--g-color-base-selection); color: var(--g-color-text-brand); font-size: 11px; flex-shrink: 0; font-weight: 600;}
.top-avatar {width: 30px; height: 30px; margin-left: var(--g-spacing-2); cursor: pointer;}
.profile-compact {justify-content: center; padding-top: var(--g-spacing-3);}
.profile-compact .profile-avatar {width: 28px; height: 28px;}
.app-content {height: 100vh; overflow-y: auto; background: var(--app-surface); min-width: 0;}
.topbar {height: 72px; background: var(--g-color-base-background); padding: 0 var(--g-spacing-8); display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--g-color-line-generic); gap: var(--g-spacing-4);}
.breadcrumbs {display: flex; align-items: center; gap: var(--g-spacing-3); color: var(--g-color-text-secondary); font-size: 12px; white-space: nowrap;}
.breadcrumb-current {color: var(--g-color-text-primary); font-weight: 500;}
.topbar-actions {display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--g-color-text-secondary);}
.global-search {--g-button-text-color: var(--g-color-text-secondary); font-size: 12px;}
kbd {font-family: inherit; color: var(--g-color-text-hint); background: var(--g-color-base-generic); font-size: 10px; border-radius: var(--g-border-radius-s); padding: 2px var(--g-spacing-1); margin-left: var(--g-spacing-3);}
.topbar-divider {width: 1px; height: 22px; background: var(--g-color-line-generic); margin: 0 var(--g-spacing-2);}
.notification-button {position: relative; display: flex;}
.notification-button i {height: 5px; width: 5px; background: var(--g-color-base-brand); border-radius: 50%; position: absolute; right: 8px; top: 6px; border: 1px solid var(--g-color-base-background); pointer-events: none;}
.main {padding: var(--g-spacing-8) var(--g-spacing-8) var(--g-spacing-4); max-width: 1740px; margin: 0 auto;}
.page-heading {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-7);}
.title-line {display: flex; align-items: center; gap: var(--g-spacing-3);}
.page-title {font-weight: 650; letter-spacing: -.8px;}
.title-count {border: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-1) var(--g-spacing-2); border-radius: var(--g-border-radius-m); font-size: 12px; color: var(--g-color-text-secondary); background: var(--g-color-base-background);}
.page-description {color: var(--g-color-text-secondary); font-size: 12px; margin: var(--g-spacing-2) 0 0; line-height: 1.5;}
.heading-actions {display: flex; gap: var(--g-spacing-2); flex-shrink: 0;}
.heading-actions .g-button {font-size: 12px;}
.metrics {display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--g-spacing-4);}
.metric-card {padding: var(--g-spacing-4) var(--g-spacing-5); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); background: var(--g-color-base-background);}
.metric-top {display: flex; align-items: center; justify-content: space-between; color: var(--g-color-text-secondary); font-size: 12px; margin-bottom: var(--g-spacing-1);}
.metric-icon {color: var(--g-color-text-secondary); display: grid; place-items: center; height: 28px; width: 28px; border-radius: var(--g-border-radius-m); background: var(--g-color-base-generic);}
.metric-icon-1, .metric-icon-3 {color: var(--g-color-text-brand); background: var(--g-color-base-positive-light);}
.metric-icon-2 {color: var(--g-color-text-warning); background: var(--g-color-base-warning-light);}
.metric-value {display: block; font-weight: 600; letter-spacing: -.9px; white-space: nowrap; font-variant-numeric: tabular-nums;}
.metric-bottom {display: flex; align-items: center; gap: var(--g-spacing-2); font-size: 10px; margin-top: var(--g-spacing-3); white-space: nowrap;}
.metric-change {display: inline-flex; align-items: center; font-size: 10px; font-weight: 500; padding: 2px var(--g-spacing-1); border-radius: var(--g-border-radius-s);}
.green {color: var(--g-color-text-positive); background: var(--g-color-base-positive-light);}
.amber {color: var(--g-color-text-warning); background: var(--g-color-base-warning-light);}
.secondary {color: var(--g-color-text-secondary);}
.overview-caption {display: flex; align-items: center; justify-content: space-between; margin: var(--g-spacing-3) 0 var(--g-spacing-5); color: var(--g-color-text-secondary); font-size: 10px;}
.overview-caption>span {display: flex; align-items: center; gap: var(--g-spacing-2);}
.overview-caption .g-button {font-size: 11px; --g-button-text-color: var(--g-color-text-secondary);}
.live-dot {display: inline-block; width: 5px; height: 5px; border-radius: 50%; background: var(--g-color-base-brand);}
.orders-panel {background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); min-width: 0; overflow: hidden;}
.status-tabs {display: flex; gap: var(--g-spacing-5); border-bottom: 1px solid var(--g-color-line-generic); padding: 0 var(--g-spacing-5); overflow-x: auto;}
.status-tab {height: 55px; position: relative; --g-button-border-radius: 0; --g-button-text-color: var(--g-color-text-secondary); --g-button-padding: 0; font-size: 12px; flex-shrink: 0;}
.status-tab.is-active {--g-button-text-color: var(--g-color-text-brand); font-weight: 600;}
.status-tab.is-active:after {position: absolute; bottom: -1px; height: 3px; content: ''; inset-inline: 0; background: var(--g-color-base-brand); border-radius: var(--g-border-radius-s) var(--g-border-radius-s) 0 0;}
.tab-count {padding: 2px 6px; margin-left: var(--g-spacing-2); border-radius: var(--g-border-radius-s); font-size: 10px; background: var(--g-color-base-generic); color: var(--g-color-text-secondary); font-weight: 400;}
.is-active .tab-count {background: var(--g-color-base-selection); color: var(--g-color-text-brand);}
.table-toolbar {display: flex; align-items: center; padding: var(--g-spacing-4) var(--g-spacing-5); gap: var(--g-spacing-2);}
.table-toolbar .g-button {font-size: 11px;}
.order-search {max-width: 330px; min-width: 180px; width: 37%; --g-text-input-background-color: var(--g-color-base-background); --g-text-input-text-color: var(--g-color-text-primary);}
.order-search .g-icon {margin-left: var(--g-spacing-3); color: var(--g-color-text-secondary);}
.toolbar-spacer {flex: 1; min-width: 0;}
.group-button.is-on {--g-button-background-color: var(--g-color-base-selection); --g-button-border-color: var(--g-color-base-selection-hover); --g-button-text-color: var(--g-color-text-brand);}
