/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import {initialOrders, statuses} from './src/data.ts';
import {createTable, getCoreRowModel, getExpandedRowModel} from '@gravity-ui/table/tanstack';
assert.equal(initialOrders.length, 248);
assert.equal(new Set(initialOrders.map(o => o.id)).size, 248);
assert.deepEqual(statuses.map(s => initialOrders.filter(o => o.status === s.id).length), [32,48,156,12]);
const data = statuses.map(s => ({id: "'`group-${s.id}`, children: initialOrders.slice(0,10).filter(o => o.status === s.id)}));
let state = {rowSelection: {}, expanded: true, columnOrder: ['"'id','customer','status'], columnPinning: {left: [],right: []}};
const table = createTable({data, columns: [{accessorKey:'id'}, {accessorKey:'customer'}, {accessorKey:'status'}], state, getRowId: o => o.id, getSubRows: o => o.children, getCoreRowModel:getCoreRowModel(), getExpandedRowModel:getExpandedRowModel(), enableRowSelection:true, enableExpanding:true, onStateChange: updater => {state = typeof updater === 'function' ? updater(state) : updater; table.setOptions(prev => ({...prev,state}));}});
assert.equal(table.getRowModel().rows.length,14);
table.getRow('group-new').toggleSelected(true);
assert(initialOrders.slice(0,3).every(o => table.getRow(o.id).getIsSelected()));
assert.equal(initialOrders.slice(3,10).some(o => table.getRow(o.id).getIsSelected()), false);
table.getRow('group-new').toggleExpanded(false);
assert.equal(table.getRowModel().rows.length,11);
table.setColumnOrder(['status','id','customer']);
assert.deepEqual(table.getAllLeafColumns().map(c => c.id), ['status','id','customer']);
console.log('Verified: 248 unique orders, correct status totals, group selection, collapsing, column reordering.');
EOF"

