.top-avatar {width: 30px; height: 30px; margin-left: var(--g-spacing-2); cursor: pointer;}
.profile-compact {justify-content: center; padding-top: var(--g-spacing-3);}
.profile-compact .profile-avatar {width: 28px; height: 28px;}
