.breadcrumb-current {color: var(--g-color-text-primary); font-weight: 500;}
.topbar-actions {display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--g-color-text-secondary);}
.global-search {--g-button-text-color: var(--g-color-text-secondary); font-size: 12px;}
kbd {font-family: inherit; color: var(--g-color-text-hint); background: var(--g-color-base-generic); font-size: 10px; border-radius: var(--g-border-radius-s); padding: 2px var(--g-spacing-1); margin-left: var(--g-spacing-3);}
.topbar-divider {width: 1px; height: 22px; background: var(--g-color-line-generic); margin: 0 var(--g-spacing-2);}
.notification-button {position: relative; display: flex;}
.notification-button i {height: 5px; width: 5px; background: var(--g-color-base-brand); border-radius: 50%; position: absolute; right: 8px; top: 6px; border: 1px solid var(--g-color-base-background); pointer-events: none;}
.main {padding: var(--g-spacing-8) var(--g-spacing-8) var(--g-spacing-4); max-width: 1740px; margin: 0 auto;}
.page-heading {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-7);}
.title-line {display: flex; align-items: center; gap: var(--g-spacing-3);}
.page-title {font-weight: 650; letter-spacing: -.8px;}
.title-count {border: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-1) var(--g-spacing-2); border-radius: var(--g-border-radius-m); font-size: 12px; color: var(--g-color-text-secondary); background: var(--g-color-base-background);}
.page-description {color: var(--g-color-text-secondary); font-size: 12px; margin: var(--g-spacing-2) 0 0; line-height: 1.5;}
.heading-actions {display: flex; gap: var(--g-spacing-2); flex-shrink: 0;}
.heading-actions .g-button {font-size: 12px;}
.metrics {display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--g-spacing-4);}
.metric-card {padding: var(--g-spacing-4) var(--g-spacing-5); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); background: var(--g-color-base-background);}
.metric-top {display: flex; align-items: center; justify-content: space-between; color: var(--g-color-text-secondary); font-size: 12px; margin-bottom: var(--g-spacing-1);}
